package cn.tbforum.api;
import cn.tbforum.domain.*; import cn.tbforum.repo.Repositories.*; import cn.tbforum.security.JwtService; import cn.tbforum.notif.NotificationService; import cn.tbforum.cache.CacheService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; import java.time.Duration; import java.time.Instant;

@RestController @Validated @RequestMapping("/api") public class Api {
 private final Users users; private final Forums forums; private final Posts posts; private final Comments comments; private final Moderators moderators; private final Interactions interactions; private final Notifications notifications; private final Follows follows; private final Favorites favorites; private final Reports reports; private final Tags tags; private final PostTags postTags; private final PasswordEncoder encoder; private final JwtService jwt; private final NotificationService notif; private final CacheService cache;
 private final HttpServletRequest request;
 public Api(Users u,Forums f,Posts p,Comments c,Moderators m,Interactions i,Notifications n,Follows fl,Favorites fv,Reports r,Tags t,PostTags pt,PasswordEncoder e,JwtService j,NotificationService ns,CacheService cs,HttpServletRequest req){users=u;forums=f;posts=p;comments=c;moderators=m;interactions=i;notifications=n;follows=fl;favorites=fv;reports=r;tags=t;postTags=pt;encoder=e;jwt=j;notif=ns;cache=cs;request=req;}
 record Credentials(@NotBlank @Size(min=3,max=40) String username,@NotBlank @Size(min=8,max=100) String password){} record Token(String token,String username){}
 record ForumInput(@NotBlank @Size(max=100) String name,@NotBlank @Pattern(regexp="[a-z0-9-]{3,64}") String slug,@Size(max=500) String description){}
 record PostInput(@NotBlank @Size(max=180) String title,@NotBlank String content){} record CommentInput(@NotBlank @Size(max=5000) String content,Long parentId){} record InteractionInput(@NotNull Interaction.Kind kind){}
 record UserView(Long id,String username,boolean verified,String avatarUrl,String bio,String signature,String role){ static UserView of(User u){return new UserView(u.id,u.username,u.verified,u.avatarUrl,u.bio,u.signature,u.role.name());}}
 record UserDetailView(Long id,String username,boolean verified,String avatarUrl,String bio,String signature,long following,long followers,boolean isFollowing,boolean isSelf,boolean mutual){ static UserDetailView of(User u,User viewer,Follows follows){boolean isSelf=viewer!=null&&viewer.id.equals(u.id);boolean following=!isSelf&&viewer!=null&&follows.findByFollowerAndFollowee(viewer,u).isPresent();boolean mutual=following&&follows.findByFollowerAndFollowee(u,viewer).isPresent();return new UserDetailView(u.id,u.username,u.verified,u.avatarUrl,u.bio,u.signature,follows.countByFollower(u),follows.countByFollowee(u),following,isSelf,mutual);}}
 record ProfileInput(@Size(min=3,max=40) String username,@Size(max=1000000) String avatarUrl,@Size(max=500) String bio,@Size(max=100) String signature){}
 record ProfileUpdateView(String token,UserView user){}
 record ForumView(Long id,String slug,String name,String description,UserView owner,String customReportReason1,String customReportReason2){static ForumView of(Forum f){return new ForumView(f.id,f.slug,f.name,f.description,UserView.of(f.owner),f.customReportReason1,f.customReportReason2);}}
 record PostView(Long id,String title,String content,String forum,String author,String authorAvatar,java.time.Instant createdAt,long views,long upvotes,long comments,boolean featured,boolean locked,boolean edited,java.time.Instant editedAt,boolean favorited,List<String> tags){static PostView of(Post p){return new PostView(p.id,p.title,p.content,p.forum.slug,p.author.username,p.author.avatarUrl,p.createdAt,p.views,p.upvotes,p.commentCount,p.featured,p.locked,p.edited,p.editedAt,false,List.of());}static PostView of(Post p,User viewer,Favorites favorites){return new PostView(p.id,p.title,p.content,p.forum.slug,p.author.username,p.author.avatarUrl,p.createdAt,p.views,p.upvotes,p.commentCount,p.featured,p.locked,p.edited,p.editedAt,viewer!=null&&favorites.existsByUserAndPost(viewer,p),List.of());}static PostView of(Post p,User viewer,Favorites favorites,List<String> tagNames){return new PostView(p.id,p.title,p.content,p.forum.slug,p.author.username,p.author.avatarUrl,p.createdAt,p.views,p.upvotes,p.commentCount,p.featured,p.locked,p.edited,p.editedAt,viewer!=null&&favorites.existsByUserAndPost(viewer,p),tagNames);}}
 /** 查询帖子的标签名列表 */
 private List<String> tagNamesOf(Post p){return postTags.findByPost(p).stream().map(pt->pt.tag.name).toList();}
 /** 批量查询帖子的标签名（避免 N+1） */
 private Map<Long,List<String>> tagNamesOf(List<Post> list){if(list.isEmpty())return Map.of();var all=postTags.findAllById(list.stream().flatMap(p->java.util.stream.Stream.of(p.id)).toList());return all.stream().collect(java.util.stream.Collectors.groupingBy(pt->pt.post.id,java.util.stream.Collectors.mapping(pt->pt.tag.name,java.util.stream.Collectors.toList())));}
 /** 封装 PostView 构建（含标签） */
 private PostView viewOf(Post p,User viewer){return PostView.of(p,viewer,favorites,tagNamesOf(p));}
 /** 从内容中解析 #标签（最多5个，2-30字符，去重） */
 private List<String> parseTags(String content){var found=new java.util.LinkedHashSet<String>();var m=java.util.regex.Pattern.compile("#([^#\\s]{2,30})").matcher(content);while(m.find()&&found.size()<5)found.add(m.group(1));return new java.util.ArrayList<>(found);}
 /** 同步帖子标签（删除旧的，解析并创建新的） */
 @Transactional private void syncTags(Post p,String content){postTags.deleteByPost(p);for(String name:parseTags(content)){Tag t=tags.findByName(name).orElseGet(()->{Tag nt=new Tag();nt.name=name;return tags.save(nt);});PostTag pt=new PostTag();pt.post=p;pt.tag=t;postTags.save(pt);t.postCount++;tags.save(t);}}
 record CommentView(Long id,String author,String authorAvatar,String content,int depth,java.time.Instant createdAt,boolean edited,java.time.Instant editedAt,boolean pinned,List<CommentView> children){}
 record NotificationView(Long id,String kind,String text,String actor,Long postId,Long commentId,java.time.Instant createdAt,boolean read){static NotificationView of(Notification n){return new NotificationView(n.id,n.kind.name(),n.text,n.actor!=null?n.actor.username:null,n.postId,n.commentId,n.createdAt,n.read);}}
 @PostMapping("/auth/register") public ResponseEntity<Token> register(@Valid @RequestBody Credentials input){if(users.findByUsername(input.username()).isPresent())throw bad("用户名已存在"); User u=new User();u.username=input.username();u.passwordHash=encoder.encode(input.password());users.save(u);return ResponseEntity.status(201).body(new Token(jwt.issue(u.username),u.username));}
 @PostMapping("/auth/login") public Token login(@Valid @RequestBody Credentials input){User u=users.findByUsername(input.username()).orElseThrow(()->unauthorized("用户名或密码错误"));if(!encoder.matches(input.password(),u.passwordHash))throw unauthorized("用户名或密码错误");return new Token(jwt.issue(u.username),u.username);}
 @GetMapping("/auth/me") public UserView me(){return UserView.of(current());}
@PostMapping("/auth/refresh") public Token refresh(){User u=current();return new Token(jwt.issue(u.username),u.username);}
 @PostMapping("/upload") public Map<String,String> upload(@RequestParam("file") org.springframework.web.multipart.MultipartFile file) throws java.io.IOException {User u=current();if(file.isEmpty())throw bad("文件不能为空");if(file.getSize()>2*1024*1024)throw bad("文件不能超过2MB");String ct=file.getContentType();if(ct==null||!ct.startsWith("image/"))throw bad("只能上传图片");String ext=ct.substring(6);String filename="avatar_"+u.id+"_"+System.currentTimeMillis()+"."+ext;java.io.File dest=new java.io.File("uploads",filename);dest.getParentFile().mkdirs();file.transferTo(dest);return Map.of("url","/uploads/"+filename);}
 @PatchMapping("/auth/me/verified") public UserView verify(){User u=current();u.verified=true;return UserView.of(users.save(u));}
 @PatchMapping("/auth/me") @Transactional public ProfileUpdateView updateProfile(@Valid @RequestBody ProfileInput input){User u=current();boolean renamed=false;if(input.username()!=null&&!input.username().equals(u.username)){if(users.findByUsername(input.username()).isPresent())throw bad("用户名已存在");u.username=input.username();renamed=true;}if(input.avatarUrl()!=null)u.avatarUrl=input.avatarUrl().isEmpty()?null:input.avatarUrl();if(input.bio()!=null)u.bio=input.bio().isEmpty()?null:input.bio();if(input.signature()!=null)u.signature=input.signature().isEmpty()?null:input.signature();users.save(u);return new ProfileUpdateView(renamed?jwt.issue(u.username):null,UserView.of(u));}
 @GetMapping("/forums") public Page<ForumView> listForums(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){String cacheKey="forums:list:"+page+":"+Math.min(size,50);if(cache.isAvailable()){String cached=cache.get(cacheKey);if(cached!=null){try{return new PageImpl<>(Arrays.asList(new com.fasterxml.jackson.databind.ObjectMapper().readValue(cached,ForumView[].class)),PageRequest.of(page,Math.min(size,50)),0);}catch(Exception ignored){}}}Page<ForumView> r=forums.findAll(PageRequest.of(page,Math.min(size,50),Sort.by("createdAt").descending())).map(ForumView::of);if(cache.isAvailable()&&page==0&&size<=20){try{cache.set(cacheKey,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(r.getContent()),Duration.ofMinutes(10));}catch(Exception ignored){}}return r;}
 @PostMapping("/forums") public ResponseEntity<ForumView> createForum(@Valid @RequestBody ForumInput input){User u=current();if(!u.verified)throw forbidden("需完成实名认证才可创建版块");if(forums.findBySlug(input.slug()).isPresent())throw bad("版块标识已存在");Forum f=new Forum();f.name=input.name();f.slug=input.slug();f.description=input.description();f.owner=u;ForumView v=ForumView.of(forums.save(f));cache.evictByPrefix("forums:list:");return ResponseEntity.status(201).body(v);}
 @GetMapping("/forums/{slug}") public ForumView forum(@PathVariable String slug){return ForumView.of(getForum(slug));}
 @PostMapping("/forums/{slug}/moderators/{username}") public ResponseEntity<Void> appoint(@PathVariable String slug,@PathVariable String username){Forum f=getForum(slug);requireOwner(f);User u=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));if(!u.verified)throw bad("小版主需完成实名认证");if(moderators.existsByForumAndUser(f,u))return ResponseEntity.noContent().build();if(moderators.countByForum(f)>=2)throw bad("最多两名小版主");ForumModerator m=new ForumModerator();m.forum=f;m.user=u;moderators.save(m);return ResponseEntity.status(201).build();}
 @GetMapping("/forums/{slug}/moderators") public List<UserView> listModerators(@PathVariable String slug){Forum f=getForum(slug);return moderators.findByForum(f).stream().map(m->UserView.of(m.user)).toList();}
 @GetMapping("/forums/{slug}/posts") public Page<PostView> listPosts(@PathVariable String slug,@RequestParam(defaultValue="latest") String order,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) Long seed){Forum f=getForum(slug);int pageSize=Math.min(size,50);User viewer=currentOrNull();if("fate".equals(order)){List<Post> all=posts.findByForumAndDeletedFalse(f);if(seed!=null)Collections.shuffle(all,new Random(seed));else Collections.shuffle(all);int total=all.size();int from=Math.min(page*pageSize,total);int to=Math.min(from+pageSize,total);List<Post> sub=all.subList(from,to);var tagMap=tagNamesOf(sub);List<PostView> slice=sub.stream().map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of()))).toList();return new PageImpl<>(slice,PageRequest.of(page,pageSize),total);}Sort sort=switch(order){case "hot"->Sort.by(Sort.Order.desc("upvotes"),Sort.Order.desc("views"));case "featured"->Sort.by(Sort.Order.desc("createdAt"));default->Sort.by(Sort.Order.desc("createdAt"));};Page<Post> result="featured".equals(order)?posts.findByForumAndFeaturedTrueAndDeletedFalse(f,PageRequest.of(page,pageSize,sort)):posts.findByForumAndDeletedFalse(f,PageRequest.of(page,pageSize,sort));var tagMap=tagNamesOf(result.getContent());return result.map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of())));}
 @PostMapping("/forums/{slug}/posts") @Transactional public ResponseEntity<PostView> createPost(@PathVariable String slug,@Valid @RequestBody PostInput input){Post p=new Post();p.forum=getForum(slug);p.author=current();p.title=input.title();p.content=input.content();posts.save(p);syncTags(p,input.content());notif.notifyMentions(p.content,p.author,p.id,null);cache.evictByPrefix("feed:");return ResponseEntity.status(201).body(viewOf(p,current()));}
 @GetMapping("/posts/{id}") @Transactional public PostView post(@PathVariable Long id){Post p=getPost(id);User viewer=currentOrNull();String viewerKey=viewer!=null?("u:"+viewer.id):("ip:"+clientIp());if(cache.tryIncrementView(viewerKey,id,Duration.ofMinutes(5))){p.views++;}return viewOf(p,viewer);}
 @DeleteMapping("/posts/{id}") public ResponseEntity<Void> deletePost(@PathVariable Long id){Post p=getPost(id);User u=current();if(!p.author.id.equals(u.id))requireModerator(p.forum);p.deleted=true;posts.save(p);return ResponseEntity.noContent().build();}
 @PatchMapping("/posts/{id}/featured") public PostView feature(@PathVariable Long id,@RequestParam boolean value){Post p=getPost(id);requireModerator(p.forum);p.featured=value;posts.save(p);if(value)notif.notify(p.author,current(),Notification.Kind.FEATURED,"你的帖子被设为精华",p.id,null);return PostView.of(p);}
 @PostMapping("/posts/{id}/interactions") @Transactional public ResponseEntity<PostView> interact(@PathVariable Long id,@Valid @RequestBody InteractionInput input){Post p=getPost(id);User u=current();var old=interactions.findByUserAndPost(u,p);if(old.isPresent()){Interaction x=old.get();if(x.kind==Interaction.Kind.UP)p.upvotes--;if(x.kind==Interaction.Kind.DOWN)p.downvotes--;if(x.kind==input.kind()){interactions.delete(x);posts.save(p);return ResponseEntity.ok(PostView.of(p));}x.kind=input.kind();}else{Interaction x=new Interaction();x.user=u;x.post=p;x.kind=input.kind();interactions.save(x);}if(input.kind()==Interaction.Kind.UP)p.upvotes++;if(input.kind()==Interaction.Kind.DOWN)p.downvotes++;posts.save(p);if(input.kind()==Interaction.Kind.UP)notif.notify(p.author,u,Notification.Kind.UPVOTE,"赞了你的帖子",p.id,null);return ResponseEntity.ok(PostView.of(p));}
 @PostMapping("/posts/{id}/comments") @Transactional public ResponseEntity<CommentView> comment(@PathVariable Long id,@Valid @RequestBody CommentInput input){Post p=getPost(id);if(p.locked)throw forbidden("帖子已锁定，无法评论");Comment c=new Comment();c.post=p;c.author=current();c.content=input.content();if(input.parentId()!=null){c.parent=comments.findById(input.parentId()).orElseThrow(()->notFound("父评论不存在"));if(!c.parent.post.id.equals(p.id))throw bad("父评论不属于该帖子");c.depth=c.parent.depth+1;c.rootId=c.parent.rootId==null?c.parent.id:c.parent.rootId;}comments.save(c);if(c.rootId==null){c.rootId=c.id;comments.save(c);}p.commentCount++;posts.save(p);notif.notify(p.author,c.author,Notification.Kind.REPLY,"回复了你的帖子",p.id,c.id);if(c.parent!=null)notif.notify(c.parent.author,c.author,Notification.Kind.REPLY,"回复了你的评论",p.id,c.id);notif.notifyMentions(c.content,c.author,p.id,c.id);return ResponseEntity.status(201).body(new CommentView(c.id,c.author.username,c.author.avatarUrl,c.content,c.depth,c.createdAt,c.edited,c.editedAt,c.pinned,List.of()));}
 @PatchMapping("/posts/{id}/comments/{commentId}") @Transactional public CommentView editComment(@PathVariable Long id,@PathVariable Long commentId,@Valid @RequestBody CommentInput input){Comment c=comments.findById(commentId).orElseThrow(()->notFound("评论不存在"));if(!c.post.id.equals(id))throw bad("评论不属于该帖子");if(!c.author.id.equals(current().id))throw forbidden("只能编辑自己的评论");c.content=input.content();c.edited=true;c.editedAt=Instant.now();comments.save(c);return new CommentView(c.id,c.author.username,c.author.avatarUrl,c.content,c.depth,c.createdAt,c.edited,c.editedAt,c.pinned,List.of());}
 @GetMapping("/posts/{id}/comments") public List<CommentView> commentTree(@PathVariable Long id){List<Comment> all=comments.findByPostAndDeletedFalseOrderByPinnedDescCreatedAtAsc(getPost(id));Map<Long,List<Comment>> groups=new HashMap<>();for(Comment c:all)groups.computeIfAbsent(c.parent==null?0L:c.parent.id,k->new ArrayList<>()).add(c);return tree(groups.getOrDefault(0L,List.of()),groups);}
 @PatchMapping("/posts/{id}/comments/{commentId}/pinned") @Transactional public CommentView pinComment(@PathVariable Long id,@PathVariable Long commentId,@RequestParam boolean value){Post p=getPost(id);requireModerator(p.forum);Comment c=comments.findById(commentId).orElseThrow(()->notFound("评论不存在"));if(!c.post.id.equals(id))throw bad("评论不属于该帖子");c.pinned=value;comments.save(c);return new CommentView(c.id,c.author.username,c.author.avatarUrl,c.content,c.depth,c.createdAt,c.edited,c.editedAt,c.pinned,List.of());}
 @GetMapping("/search") public Page<PostView> search(@RequestParam @NotBlank String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){current();Page<Post> result=posts.search(q,PageRequest.of(page,Math.min(size,50),Sort.by("createdAt").descending()));var tagMap=tagNamesOf(result.getContent());return result.map(p->PostView.of(p,null,favorites,tagMap.getOrDefault(p.id,List.of())));}
 /** 全站帖子流：latest（最新）/ hot（热门）/ featured（精华）/ fate（随缘） */
 @GetMapping("/posts/feed") public Page<PostView> feed(@RequestParam(defaultValue="latest") String order,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) Long seed){
     int pageSize=Math.min(size,50);
     User viewer=currentOrNull();
     // 随缘排序：全列表 shuffle 后分页（不缓存，保证每次随机）
     if("fate".equals(order)){
         List<Post> all=posts.findByDeletedFalse();
         if(seed!=null)Collections.shuffle(all,new Random(seed));else Collections.shuffle(all);
         int total=all.size();int from=Math.min(page*pageSize,total);int to=Math.min(from+pageSize,total);
         List<Post> slice=all.subList(from,to);
         Map<Long,List<String>> tagMap=tagNamesOf(slice);
         List<PostView> views=slice.stream().map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of()))).toList();
         return new PageImpl<>(views,PageRequest.of(page,pageSize),total);
     }
     // 精华排序：全站精华帖子分页（不缓存，保证精华状态实时）
     if("featured".equals(order)){
         Page<Post> result=posts.findByFeaturedTrueAndDeletedFalse(PageRequest.of(page,pageSize,Sort.by(Sort.Order.desc("createdAt"))));
         Map<Long,List<String>> tagMap=tagNamesOf(result.getContent());
         return result.map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of())));
     }
     String cacheKey="feed:"+order+":"+page+":"+pageSize;
     if(cache.isAvailable()){String cached=cache.get(cacheKey);if(cached!=null){try{return new PageImpl<>(Arrays.asList(new com.fasterxml.jackson.databind.ObjectMapper().readValue(cached,PostView[].class)),PageRequest.of(page,pageSize),0);}catch(Exception ignored){}}}
     if("hot".equals(order)){
         // 24h 内热门帖子：JPQL 查询排序
         Instant since=Instant.now().minusSeconds(86400);
         List<Post> hot=posts.findHotSince(since);
         int total=hot.size();int from=Math.min(page*pageSize,total);int to=Math.min(from+pageSize,total);
         List<Post> slice=hot.subList(from,to);
         Map<Long,List<String>> tagMap=tagNamesOf(slice);
         List<PostView> views=slice.stream().map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of()))).toList();
         Page<PostView> result=new PageImpl<>(views,PageRequest.of(page,pageSize),total);
         if(cache.isAvailable()&&page==0){try{cache.set(cacheKey,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(views),Duration.ofMinutes(2));}catch(Exception ignored){}}
         return result;
     }
     Page<Post> result=posts.findAllByDeletedFalseOrderByCreatedAtDesc(PageRequest.of(page,pageSize));
     Map<Long,List<String>> tagMap=tagNamesOf(result.getContent());
     Page<PostView> r=result.map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of())));
     if(cache.isAvailable()&&page==0){try{cache.set(cacheKey,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(r.getContent()),Duration.ofMinutes(2));}catch(Exception ignored){}}
     return r;
 }
 /** 热门标签列表 */
 @GetMapping("/tags") public List<TagView> popularTags(){return tags.findTop50ByOrderByPostCountDesc().stream().map(TagView::of).toList();}
 /** 按标签筛选帖子 */
 @GetMapping("/tags/{name}/posts") public Page<PostView> postsByTag(@PathVariable String name,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){Tag t=tags.findByName(name).orElseThrow(()->notFound("标签不存在"));User viewer=currentOrNull();Page<Post> result=postTags.findPostsByTag(t,PageRequest.of(page,Math.min(size,50)));Map<Long,List<String>> tagMap=tagNamesOf(result.getContent());return result.map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of())));}
 record TagView(Long id,String name,long postCount){static TagView of(Tag t){return new TagView(t.id,t.name,t.postCount);}}
 @GetMapping("/users/{username}") public UserDetailView user(@PathVariable String username){User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));return UserDetailView.of(target,currentOrNull(),follows);}
 @GetMapping("/users/search") public List<UserView> searchUsers(@RequestParam @NotBlank String q){return users.findTop10ByUsernameContainingIgnoreCase(q).stream().map(UserView::of).toList();}
 @PostMapping("/users/{username}/follow") @Transactional public ResponseEntity<Void> follow(@PathVariable String username){User u=current();User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));if(u.id.equals(target.id))throw bad("不能关注自己");if(follows.findByFollowerAndFollowee(u,target).isEmpty()){Follow f=new Follow();f.follower=u;f.followee=target;follows.save(f);notif.notify(target,u,Notification.Kind.FOLLOW,"关注了你",null,null);}return ResponseEntity.status(201).build();}
 @DeleteMapping("/users/{username}/follow") @Transactional public ResponseEntity<Void> unfollow(@PathVariable String username){User u=current();User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));follows.deleteByFollowerAndFollowee(u,target);return ResponseEntity.noContent().build();}
 @GetMapping("/users/{username}/followers") public List<UserView> followers(@PathVariable String username){User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));return follows.findByFolloweeOrderByCreatedAtDesc(target).stream().map(f->UserView.of(f.follower)).toList();}
 @GetMapping("/users/{username}/following") public List<UserView> following(@PathVariable String username){User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));return follows.findByFollowerOrderByCreatedAtDesc(target).stream().map(f->UserView.of(f.followee)).toList();}
 @PostMapping("/posts/{id}/favorite") @Transactional public ResponseEntity<PostView> favorite(@PathVariable Long id){Post p=getPost(id);User u=current();if(!favorites.existsByUserAndPost(u,p)){Favorite f=new Favorite();f.user=u;f.post=p;favorites.save(f);}return ResponseEntity.status(201).body(PostView.of(p,u,favorites));}
 @DeleteMapping("/posts/{id}/favorite") @Transactional public ResponseEntity<PostView> unfavorite(@PathVariable Long id){Post p=getPost(id);User u=current();favorites.deleteByUserAndPost(u,p);return ResponseEntity.ok(PostView.of(p,u,favorites));}
 @GetMapping("/users/me/favorites") public Page<PostView> myFavorites(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){User u=current();Page<Post> result=favorites.findPostsByUser(u,PageRequest.of(page,Math.min(size,50)));var tagMap=tagNamesOf(result.getContent());return result.map(p->PostView.of(p,u,favorites,tagMap.getOrDefault(p.id,List.of())));}
 @GetMapping("/users/{username}/posts") public Page<PostView> userPosts(@PathVariable String username,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){User target=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));User viewer=currentOrNull();Page<Post> result=posts.findByAuthorAndDeletedFalse(target,PageRequest.of(page,Math.min(size,50),Sort.by("createdAt").descending()));var tagMap=tagNamesOf(result.getContent());return result.map(p->PostView.of(p,viewer,favorites,tagMap.getOrDefault(p.id,List.of())));}
 @PatchMapping("/posts/{id}") @Transactional public PostView editPost(@PathVariable Long id,@Valid @RequestBody PostInput input){Post p=getPost(id);if(!p.author.id.equals(current().id))throw forbidden("只能编辑自己的帖子");p.title=input.title();p.content=input.content();p.edited=true;p.editedAt=Instant.now();posts.save(p);syncTags(p,input.content());cache.evictByPrefix("feed:");return viewOf(p,current());}
 @GetMapping("/notifications") public List<NotificationView> listNotifications(){return notifications.findTop20ByUserOrderByCreatedAtDesc(current()).stream().map(NotificationView::of).toList();}
 @GetMapping("/notifications/unread-count") public Map<String,Long> unreadCount(){return Map.of("count",notifications.countByUserAndReadFalse(current()));}
 @PatchMapping("/notifications/{id}/read") public ResponseEntity<Void> markRead(@PathVariable Long id){Notification n=notifications.findById(id).orElseThrow(()->notFound("通知不存在"));if(!n.user.id.equals(current().id))throw forbidden("无权操作");n.read=true;notifications.save(n);return ResponseEntity.noContent().build();}
 @PatchMapping("/notifications/read-all") public ResponseEntity<Void> markAllRead(){for(Notification n:notifications.findByUserAndReadFalse(current())){n.read=true;notifications.save(n);}return ResponseEntity.noContent().build();}
 @DeleteMapping("/forums/{slug}/moderators/{username}") @Transactional public ResponseEntity<Void> removeModerator(@PathVariable String slug,@PathVariable String username){Forum f=getForum(slug);requireOwner(f);User u=users.findByUsername(username).orElseThrow(()->notFound("用户不存在"));moderators.deleteByForumAndUser(f,u);return ResponseEntity.noContent().build();}
 @PatchMapping("/posts/{id}/locked") @Transactional public PostView lock(@PathVariable Long id,@RequestParam boolean value){Post p=getPost(id);requireModerator(p.forum);p.locked=value;posts.save(p);return PostView.of(p);}
 record ReportReasons(List<String> standard,List<String> custom){}
 @GetMapping("/forums/{slug}/report-reasons") public ReportReasons reportReasons(@PathVariable String slug){Forum f=getForum(slug);List<String> custom=new ArrayList<>();if(f.customReportReason1!=null&&!f.customReportReason1.isBlank())custom.add(f.customReportReason1);if(f.customReportReason2!=null&&!f.customReportReason2.isBlank())custom.add(f.customReportReason2);return new ReportReasons(List.of("垃圾广告/营销","人身攻击/辱骂","色情低俗","违法违规","造谣传谣","引战/恶意刷屏","其他"),custom);}
 record CustomReasonsInput(String reason1,String reason2){}
 @PatchMapping("/forums/{slug}/report-reasons") @Transactional public ForumView updateReportReasons(@PathVariable String slug,@Valid @RequestBody CustomReasonsInput input){Forum f=getForum(slug);requireModerator(f);String r1=input.reason1()==null?"":input.reason1().trim();String r2=input.reason2()==null?"":input.reason2().trim();if(r1.length()>60||r2.length()>60)throw bad("举报原因长度不能超过60");if(!r1.isEmpty()&&r1.equals(r2))throw bad("两个特色原因不能相同");f.customReportReason1=r1.isEmpty()?null:r1;f.customReportReason2=r2.isEmpty()?null:r2;return ForumView.of(forums.save(f));}
 record ReportInput(@NotNull Report.TargetType targetType,@NotNull Long targetId,@NotBlank @Size(max=80) String reason){}
 @PostMapping("/reports") @Transactional public ResponseEntity<Void> report(@Valid @RequestBody ReportInput input){User u=current();if(reports.existsByReporterAndTargetTypeAndTargetId(u,input.targetType(),input.targetId()))throw bad("你已举报过该内容");if(input.targetType()==Report.TargetType.POST){Post p=posts.findById(input.targetId()).orElseThrow(()->notFound("帖子不存在"));if(p.deleted)throw notFound("帖子不存在");}else{Comment c=comments.findById(input.targetId()).orElseThrow(()->notFound("评论不存在"));if(c.deleted)throw notFound("评论不存在");}Report r=new Report();r.reporter=u;r.targetType=input.targetType();r.targetId=input.targetId();r.reason=input.reason();reports.save(r);return ResponseEntity.status(201).build();}
 record ReportView(Long id,String reporter,String targetType,Long targetId,String reason,java.time.Instant createdAt,String status,String handledBy,java.time.Instant handledAt){static ReportView of(Report r){return new ReportView(r.id,r.reporter.username,r.targetType.name(),r.targetId,r.reason,r.createdAt,r.status.name(),r.handledBy!=null?r.handledBy.username:null,r.handledAt);}}
 @GetMapping("/admin/reports") public Page<ReportView> listReports(@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){requireAdmin();Pageable p=PageRequest.of(page,Math.min(size,50));if(status==null||status.isBlank())return reports.findAllByOrderByCreatedAtDesc(p).map(ReportView::of);Report.Status s;try{s=Report.Status.valueOf(status.toUpperCase());}catch(Exception e){throw bad("无效的状态");}return reports.findByStatusOrderByCreatedAtDesc(s,p).map(ReportView::of);}
 @GetMapping("/admin/reports/count") public Map<String,Long> reportCount(@RequestParam(required=false) String status){requireAdmin();if(status==null||status.isBlank()){Map<String,Long> m=new HashMap<>();m.put("total",reports.count());m.put("pending",reports.countByStatus(Report.Status.PENDING));return m;}Report.Status s;try{s=Report.Status.valueOf(status.toUpperCase());}catch(Exception e){throw bad("无效的状态");}return Map.of("count",reports.countByStatus(s));}
 @GetMapping("/admin/reports/target") public List<ReportView> reportsForTarget(@RequestParam String type,@RequestParam Long id){requireAdmin();Report.TargetType t;try{t=Report.TargetType.valueOf(type.toUpperCase());}catch(Exception e){throw bad("无效的类型");}return reports.findByTargetTypeAndTargetId(t,id).stream().map(ReportView::of).toList();}
 @PatchMapping("/admin/reports/{id}") @Transactional public ReportView handleReport(@PathVariable Long id,@RequestParam String status){requireAdmin();Report r=reports.findById(id).orElseThrow(()->notFound("举报记录不存在"));Report.Status s;try{s=Report.Status.valueOf(status.toUpperCase());}catch(Exception e){throw bad("无效的状态");}if(r.status!=Report.Status.PENDING)throw bad("该举报已处理");r.status=s;r.handledBy=current();r.handledAt=Instant.now();return ReportView.of(reports.save(r));}
 private void requireAdmin(){if(current().role!=Role.ADMIN)throw forbidden("需要管理员权限");}
 /** 获取客户端真实 IP（处理反向代理头） */
 private String clientIp(){String xff=request.getHeader("X-Forwarded-For");if(xff!=null&&!xff.isBlank()){int comma=xff.indexOf(',');return comma>0?xff.substring(0,comma).trim():xff.trim();}String real=request.getHeader("X-Real-IP");if(real!=null&&!real.isBlank())return real;return request.getRemoteAddr();}
 private List<CommentView> tree(List<Comment> source,Map<Long,List<Comment>> groups){return source.stream().map(c->new CommentView(c.id,c.author.username,c.author.avatarUrl,c.content,c.depth,c.createdAt,c.edited,c.editedAt,c.pinned,tree(groups.getOrDefault(c.id,List.of()),groups))).toList();}
 private User current(){String name=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getName();if(name==null||"anonymousUser".equals(name))throw unauthorized("请先登录");return users.findByUsername(name).orElseThrow(()->unauthorized("登录已失效"));} private User currentOrNull(){String name=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getName();if(name==null||"anonymousUser".equals(name))return null;return users.findByUsername(name).orElse(null);} private Forum getForum(String s){return forums.findBySlug(s).orElseThrow(()->notFound("版块不存在"));} private Post getPost(Long id){Post p=posts.findById(id).orElseThrow(()->notFound("帖子不存在"));if(p.deleted)throw notFound("帖子不存在");return p;} private void requireOwner(Forum f){if(!f.owner.id.equals(current().id))throw forbidden("仅版主可执行此操作");} private void requireModerator(Forum f){User u=current();if(!f.owner.id.equals(u.id)&&!moderators.existsByForumAndUser(f,u)&&u.role!=Role.ADMIN)throw forbidden("需要版主或小版主权限");}
 private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException unauthorized(String m){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,m);}private static ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
